"""Private stdio bridge. Only allowlisted investigator tools are dispatchable."""

import json
import sys
from pathlib import Path

from ndfeb_sps.computational_workflow import investigator_interface
from ndfeb_sps.contracts import ContractError
from ndfeb_sps.operator import Campaign

from .controller import INSTRUCTIONS, TOOLS, Investigator


def main():
    investigator = None
    campaign = None
    for line in sys.stdin:
        request_id = None
        try:
            if len(line.encode()) > 8 * 1024 * 1024:
                raise ValueError("bridge request exceeds 8 MiB")
            message = json.loads(line)
            request_id = message["id"]
            method, params = message["method"], message.get("params", {})
            if method == "init":
                if investigator is not None:
                    raise ValueError("bridge already initialized")
                campaign = Campaign.open(Path(params["campaign"]))
                investigator = Investigator(campaign, Path(params["directory"]), sources=params.get("sources"))
                instructions, tools = investigator_interface(investigator.sources, INSTRUCTIONS, TOOLS)
                result = {"instructions": instructions, "tools": tools,
                          "public_state": investigator.state(summary=True)}
            elif investigator is None:
                raise ValueError("initialize bridge first")
            elif method == "state":
                result = investigator.state(summary=params.get("summary", False))
            elif method == "tool":
                result = investigator.call(params["call_id"], params["name"], params["arguments"])
            elif method == "recover_tool":
                previous = investigator.db.execute("SELECT intent,result FROM calls WHERE id=?", (params["call_id"],)).fetchone()
                if previous is None:
                    raise ValueError("tool was never started; no automatic dispatch on restore")
                if previous["intent"] is None and previous["result"] is None:
                    raise ValueError("tool has no durable intent or committed result; no automatic dispatch on restore")
                result = investigator.call(params["call_id"], params["name"], params["arguments"])
            else:
                raise ValueError("unknown bridge method")
            response = {"id": request_id, "result": result}
        except Exception as error:  # noqa: BLE001 -- RPC must return a sanitized error without killing persistent state.
            # User-visible tool validation is useful scientific feedback, but never
            # copy arbitrary host exception text/paths into inference or logs.
            visible = {"type": type(error).__name__, "code": "tool_contract_rejected",
                       "message": "Host or bridge error; operator must inspect private diagnostics. No hidden evidence released."}
            if isinstance(error, (ContractError, ValueError, TypeError, KeyError)):
                visible["message"] = str(error)[:2048]
            if hasattr(error, "public_details"):
                visible.update(code="scientific_computation_failed", details=error.public_details)
            response = {"id": request_id, "error": visible}
        print(json.dumps(response, allow_nan=False), flush=True)
    if investigator is not None:
        investigator.close()
    if campaign is not None:
        campaign.close()


if __name__ == "__main__":
    main()
